def run_agent(client, tools, dispatch, messages, max_turns=8):
    for _ in range(max_turns):
        resp = client.messages.create(model="claude-sonnet-4-5",
            max_tokens=1024, tools=tools, messages=messages)
        if resp.stop_reason != "tool_use":
            return resp  # final answer -> stop
        messages.append({"role": "assistant", "content": resp.content})
        results = []
        for block in resp.content:
            if block.type == "tool_use":
                out = dispatch[block.name](**block.input)
                results.append({"type": "tool_result",
                    "tool_use_id": block.id, "content": str(out)})
        # TODO: append the tool_result message so the next turn sees it
        # messages.append( ??? )
    raise RuntimeError("turn budget exhausted")
